import {QUEST_KEY,NAMES,POWERS,MISSIONS,freshQuest,readQuest,writeQuest,wakeToad,makeSite,packSite,unpackSite,usePower,readyToBrush,completeMission,placeRelic} from './quest-model.js';
import {loadAdventure} from './adventure-model.js';
import {itemById} from './adventure-data.js';
import {ARTIFACT_STORIES} from './artifact-stories.js';
import {drawCharacter} from './characters.js';
import {drawArtifact} from './artwork.js';
import {drawGeneratedArtifact,paintMaterial} from './generated-art.js';
import {createRenderer} from './renderer.js';
import {layoutGrid,cellAt} from './grid.js';
import {attachInput} from './input.js';
import {topLayer} from './dig-model.js';
import {createSfx} from './sfx.js';

const app=document.querySelector('#quest-app'),status=document.querySelector('#save-status'),saveButton=document.querySelector('#btn-save'),sfx=createSfx();
let storage;try{storage=localStorage;}catch{}
let state=readQuest(storage,loadAdventure(storage)),saved=null;try{saved=storage?.getItem(QUEST_KEY)||null;}catch{}
let view='',site=null,renderer=null,canvas=null,layout=null,detach=null,n=0,used=[],scanned=false,tool='frog',busy=false,token=0,replay=false,selected='',patches=new Set(),lastCell=-1;
let birdPos={x:.15,y:.8},birdGoal=null,lastFrame=0,discoveryUntil=0;
const reduced=matchMedia('(prefers-reduced-motion: reduce)');
const actor=(who,cls='')=>`<canvas class="q-actor ${cls}" data-actor="${who}" role="img" aria-label="${NAMES[who]} 토우"></canvas>`;
const art=(id,cls='')=>`<canvas class="q-art ${cls}" data-art="${id}" role="img" aria-label="${itemById(id).name} 놀이용 그림"></canvas>`;
const button=(text,action,cls='')=>`<button type="button" class="${cls}" data-action="${action}">${text}</button>`;
function capture(){if(view==='dig'&&site&&!replay&&!site.done)state.dig=packSite(n,site,used,scanned);}
function dirty(){status.textContent=JSON.stringify(state)===saved?'저장한 기록이야':'저장 안 된 진행이 있어';document.querySelector('#save-controls').dataset.dirty=String(JSON.stringify(state)!==saved);}
function render(next,html){capture();detach?.();detach=null;token++;busy=false;saveButton.disabled=false;view=next;renderer=null;canvas=null;app.dataset.view=next;app.innerHTML=html;app.scrollTop=0;app.querySelector('h1,h2')?.focus({preventScroll:true});paint(0);dirty();}
function nav(title,sub=''){return `<header class="q-top"><div><small>${sub||'토우 탐험대'}</small><h2 tabindex="-1">${title}</h2></div><nav aria-label="탐험 메뉴">${button('첫 화면','home')}${button('모험 지도','map')}${button('토우 친구','friends')}${button('모은 유물','museum')}</nav></header>`;}
function home(){render('home',`<header class="q-home-top"><strong>✦ 토우 탐험대</strong><span>친구가 늘면 발굴도 달라져!</span></header><div class="q-home-content"><div class="q-home-copy"><p>흙 속에 잠든 친구들을 깨워 줘!</p><h1 tabindex="-1"><span>토우 친구들과</span><br>신라 탐험!</h1><p class="q-home-description">두꺼비는 폴짝, 새는 훨훨.<br>친구의 능력으로 다음 유물을 찾아봐.</p><div class="q-home-actions">${button(state.friends.length?'탐험 이어가기':'탐험 시작하기','continue','q-primary')}${button('탐험 새로 시작하기','new','q-light')}</div><small>새 모험을 저장하면 이전 기록이 바뀌어.</small><div class="q-home-progress">토우 ${state.friends.length} / 4 · 기억 ${state.done.length} / 6</div></div><div class="q-home-friends">${['frog','bird','turtle','snake'].map(w=>actor(w,'hero-'+w)).join('')}<p>흙을 걷고, 돌을 밀고,<br>숨은 유물까지 함께!</p></div></div>`);}
function map(){render('map',`${nav('친구와 함께, 다음 발굴로',`${state.done.length} / 6 기억을 모았어`)}<section class="q-next"><div><small>${state.step>=6?'우리 탐험대의 다음 놀이':'지금 할 일'}</small><h3>${state.step>=6?'열린 구역에서 다시 발굴해 볼까?':MISSIONS[state.step].title}</h3><p>${state.step>=6?'친구 네 명의 능력을 자유롭게 써 봐.':MISSIONS[state.step].goal}</p></div>${button(state.step>=6?'완성한 기억 지도':'바로 발굴하러 가기',state.step>=6?'ending':'continue','q-primary')}</section><div class="q-journey">${MISSIONS.map((m,i)=>`<button type="button" class="q-node ${i===state.step?'current':''} ${i<state.step?'done':''}" data-mission="${i}" ${i>state.step?'disabled':''}><span class="q-node-number">${i<state.step?'✓':i+1}</span>${art(m.id)}<small>${i<3?'첫 번째 무덤':'두 번째 무덤'}</small><strong>${m.title}</strong><span>${i<state.step?'능력으로 다시 발굴':i===state.step?'지금 출발!':'앞선 발굴을 마치면 열려'}</span>${m.reward?`<div class="q-node-prize">${actor(m.reward)}<b>${NAMES[m.reward]} 합류</b></div>`:''}</button>`).join('')}</div><p class="q-footnote">전시는 언제든 선택해서 해도 돼. 다음 모험은 발굴로 열려!</p>`);}
function wake(){patches=new Set();render('wake',`${nav('첫 친구가 흙 속에서 꼼지락!','첫 번째 기억 · 두꺼비를 깨워 줘')}<div class="q-wake">${actor('frog')}${[0,1,2].map(i=>`<button type="button" data-patch="${i}" class="q-clay patch-${i}" aria-label="${i+1}번 흙 걷기">쓱쓱</button>`).join('')}</div><p class="q-speech" role="status">흙 세 곳을 톡톡 걷으면 두꺼비가 깨어나!</p>${button('두꺼비와 발굴 시작!','wake-go','q-primary hidden')}`);}
function enter(index=state.step){if(index>=6){ending();return;}if(index>state.step)return;n=index;replay=index<state.step;if(!state.friends.includes('frog')){wake();return;}if(MISSIONS[index].survey){survey();return;}dig();}
function dig(){const restored=unpackSite(n,replay?null:state.dig);site=restored.dig;used=restored.used;scanned=restored.scanned;tool=MISSIONS[n].need.find(w=>!used.includes(w))||'brush';lastCell=-1;discoveryUntil=0;
 render('dig',`${nav(MISSIONS[n].title,`${n+1} / 6 · ${MISSIONS[n].place}${replay?' · 다시 발굴':''}`)}<div class="q-dig-instruction"><span id="q-step">${MISSIONS[n].goal}</span><strong id="q-progress">0 / 6 조각</strong></div><div class="q-dig-stage"><canvas id="dig" aria-label="토우 능력으로 흙과 돌을 걷고, 붓으로 발굴하는 곳"></canvas><div id="q-search-marks" aria-label="탐색할 흙더미">${[25,42,57].map((cell,i)=>`<button type="button" data-scan-cell="${cell}" aria-label="${i+1}번 흔적 탐색">?</button>`).join('')}</div><div id="q-power-effect" aria-hidden="true">${actor(tool==='brush'?'frog':tool)}</div><div id="q-discovery" class="hidden" role="status"><h2>찾았다!</h2><p>${itemById(MISSIONS[n].id).name}</p></div></div><div class="q-toolbox" role="group" aria-label="발굴 도구">${['frog','bird','turtle','snake'].map(w=>`<button type="button" data-tool="${w}" ${state.friends.includes(w)?'':'disabled'}>${actor(w)}<strong>${NAMES[w]}</strong><span>${state.friends.includes(w)?POWERS[w]:'앞선 발굴에서 만날 친구'}</span></button>`).join('')}<button type="button" data-tool="brush"><b class="q-brush">✦</b><strong>손과 붓</strong><span>마지막은 살살</span></button></div><p id="q-help" class="q-speech" role="status"></p><p class="q-footnote">토우의 힘은 상상 놀이야. 실제 유물은 전문가가 손과 붓으로 조심히 다뤄.</p>`);
 canvas=app.querySelector('#dig');renderer=createRenderer(canvas);renderer.setArtifact(MISSIONS[n].id);renderer.setScene(n>=3);renderer.setCrew(state.friends);resize();
 detach=attachInput(canvas,{getLayout:()=>layout,getState:()=>view==='dig'&&tool==='brush'&&!busy&&readyToBrush(n,used)?site:null,onEvents:events,onRub:cell=>renderer.addDust(cell,layout,performance.now()),onBrush:cell=>renderer.addDust(cell,layout,performance.now(),'wood'),onTouchCell:cell=>{lastCell=cell;},onRockDrag:()=>say('돌은 거북에게 맡기거나, 천천히 톡톡 두드려 봐.')});
 canvas.addEventListener('pointerdown',e=>{if(tool==='brush'||busy)return;const r=canvas.getBoundingClientRect(),dp=canvas.width/r.width,cell=cellAt(layout,(e.clientX-r.left)*dp,(e.clientY-r.top)*dp);if(cell>=0)power(cell);});
 canvas.addEventListener('pointerup',()=>{capture();dirty();});canvas.addEventListener('pointercancel',()=>{capture();dirty();});updateTools();
}
function resize(){if(!canvas||view!=='dig')return;const r=canvas.getBoundingClientRect(),dp=Math.min(devicePixelRatio||1,2);canvas.width=Math.round(r.width*dp);canvas.height=Math.round(r.height*dp);layout=layoutGrid({width:canvas.width,height:canvas.height-42*dp,cols:12,rows:7,padding:14*dp});layout.y0+=8*dp;
 for(const b of app.querySelectorAll('[data-scan-cell]')){const cell=Number(b.dataset.scanCell);b.style.left=`${(layout.x0+(cell%12+.5)*layout.cell)/dp}px`;b.style.top=`${(layout.y0+(Math.floor(cell/12)+.5)*layout.cell)/dp}px`;}}
window.addEventListener('resize',resize);
function say(text){const e=app.querySelector('#q-help,.q-speech');if(e)e.textContent=text;}
function updateTools(){if(view!=='dig')return;for(const b of app.querySelectorAll('[data-tool]')){b.setAttribute('aria-pressed',String(b.dataset.tool===tool));b.classList.toggle('power-done',used.includes(b.dataset.tool));}const marks=app.querySelector('#q-search-marks'),cells=[...site.artifactCells];
 const targets=tool==='bird'?(scanned?[]:[25,42,57]):tool==='brush'?[]:[cells[1],cells.at(-2)].filter(cell=>tool==='frog'?site.soil[cell]>0:tool==='turtle'?site.soil[cell]===0&&site.rock[cell]>0:site.soil[cell]===0&&site.rock[cell]===0&&site.wood[cell]>.4);
 marks.innerHTML=targets.map((cell,i)=>`<button type="button" data-scan-cell="${cell}" data-kind="${tool}" aria-label="${i+1}번 ${POWERS[tool]||'탐색'} 자리">${{bird:'?',frog:'폴짝',turtle:'밀기',snake:'틈'}[tool]}</button>`).join('');marks.classList.toggle('hidden',!targets.length);resize();app.querySelector('#q-progress').textContent=`${site.revealed.size} / ${site.artifactCells.size} 조각`;
 const needed=MISSIONS[n].need.filter(w=>!used.includes(w));app.querySelector('#q-step').textContent=needed.length?`이번 발굴: ${needed.map(w=>NAMES[w]).join(' + ')}의 능력을 써 봐!`:'이제 손과 붓으로 마지막 층을 살살 걷어 줘.';
 say(tool==='brush'?(needed.length?`먼저 ${needed.map(w=>NAMES[w]).join(', ')}의 능력을 써 줘.`:'나무 위를 천천히 쓱쓱! 남은 흙은 문지르고 돌은 톡톡.'):{frog:'두꺼비를 골랐어. 흙 위에서 착지할 곳을 톡!',bird:'새를 골랐어. 물음표나 흙더미를 눌러 위치를 찾아봐.',turtle:'거북을 골랐어. 흙을 걷어 드러난 돌을 톡!',snake:'뱀을 골랐어. 흙과 돌 아래 나무 틈을 톡!'}[tool]);if(scanned)renderer?.hint([...site.artifactCells],performance.now()+60000);}
async function power(cell){if(busy||view!=='dig')return;sfx.unlock();const who=tool;if(!state.friends.includes(who))return;busy=true;saveButton.disabled=true;const epoch=token,fx=app.querySelector('#q-power-effect'),dp=canvas.width/canvas.clientWidth;
 fx.innerHTML=actor(who);fx.style.left=`${(layout.x0+(cell%12+.5)*layout.cell)/dp}px`;fx.style.top=`${(layout.y0+(Math.floor(cell/12)+.5)*layout.cell)/dp}px`;fx.dataset.power=who;fx.classList.add('active');paint(performance.now());
 if(!reduced.matches)await new Promise(r=>setTimeout(r,360));if(epoch!==token)return;
 const result=usePower(state,n,site,who,cell,used,performance.now());if(result.scanned){scanned=true;renderer.hint([...site.artifactCells],performance.now()+60000);}if(result.ok){sfx.glimmer();renderer.addDust(cell,layout,performance.now(),who==='turtle'?'rock':'soil');renderer.react('glimmer',performance.now());}else sfx.tap();events(result.events);busy=false;saveButton.disabled=false;fx.classList.remove('active');capture();dirty();updateTools();say(result.message);}
function events(list){if(!renderer)return;for(const e of list){if(e.type==='tooHard'){renderer.react('tooHard',performance.now());say('살살~ 천천히 쓸면 유물이 드러나!');}if(e.type==='collapse'){renderer.react('collapse',performance.now());say('와르르! 괜찮아, 거북이 다시 도와줄 거야.');}if(e.type==='chip')sfx.tap();if(e.type==='glimmer')sfx.glimmer();if(e.type==='artifactCell')app.querySelector('#q-progress').textContent=`${site.revealed.size} / ${site.artifactCells.size} 조각`;if(e.type==='artifactRevealed'){found();return;}}}
function found(){if(discoveryUntil||!readyToBrush(n,used))return;if(replay)state.practice++;else if(!completeMission(state,n,site,used))return;dirty();discoveryUntil=performance.now()+1700;busy=true;saveButton.disabled=true;renderer.react('artifactRevealed',performance.now());renderer.flash(500,performance.now());app.querySelector('#q-discovery').classList.remove('hidden');sfx.found();const epoch=token,index=n,wasReplay=replay;setTimeout(()=>{if(token!==epoch)return;reward(index,wasReplay);},reduced.matches?150:1700);}
function reward(index,again=false){const m=MISSIONS[index],f=ARTIFACT_STORIES[m.id];render('reward',`${nav(again?'다시 찾아도 반짝!':'유물도, 새 능력도 찾았어!',`${index+1}번째 기억`)}<div class="q-reward-layout"><div class="q-found-art">${art(m.id)}<h3>${itemById(m.id).name}</h3><div class="q-passport"><span>${f.period}</span><span>${f.place}</span></div><p>${f.what}</p>${button('유물 이야기 더 보기','facts:'+m.id,'q-small')}</div><div class="q-new-friend">${m.reward&&!again?`<small>새 친구 합류!</small>${actor(m.reward)}<h3>${NAMES[m.reward]}의 ${POWERS[m.reward]}</h3><p>${{bird:'다음 유물은 흙 속에 숨어 있어. 내가 위에서 찾아줄게!',turtle:'다음엔 단단한 돌이 기다려. 내 등으로 밀어줄게!',snake:'두 번째 무덤의 좁은 틈? 구불구불, 내 차례야!'}[m.reward]}</p>`:`<div class="q-team-row">${state.friends.map(w=>actor(w)).join('')}</div><h3>${index===4?'이제 두 봉분의 비밀만 남았어!':'친구들과 다음 기억으로!'}</h3><p>${m.story}</p>`}${button(index===4?'새와 두 봉분 조사하기':state.step>=6?'완성한 기억 지도 보기':'새 능력으로 다음 발굴!',state.step>=6?'ending':'continue','q-primary')}${button('모험 지도','map','q-small')}</div></div>`);}
function survey(){birdPos={x:.12,y:.8};birdGoal=null;render('survey',`${nav('새와 두 언덕의 기억 잇기','마지막 탐험 · 황남대총에서 착안')}<p class="q-speech">봉분을 누르면 새가 날아가. 가까이 가서 ‘내려다보기’!</p><div class="q-survey-board"><button type="button" data-survey-target="0" style="left:38%;top:57%" aria-label="남쪽 봉분으로 날기">${state.survey.includes(0)?'✓':'남쪽 봉분'}</button><button type="button" data-survey-target="1" style="left:68%;top:37%" aria-label="북쪽 봉분으로 날기">${state.survey.includes(1)?'✓':'북쪽 봉분'}</button><div id="q-survey-bird">${actor('bird')}</div></div><div class="q-survey-controls">${button('내려다보기','scan','q-primary')}<span id="q-survey-count">${state.survey.length} / 2 봉분 조사</span><div class="q-flight-pad" aria-label="새 이동">${[[0,-1,'↑'],[-1,0,'←'],[0,1,'↓'],[1,0,'→']].map(([dx,dy,t])=>`<button data-fly="${dx},${dy}" aria-label="${t} 방향 날기">${t}</button>`).join('')}</div></div>`);app.querySelector('.q-survey-board').addEventListener('click',e=>{if(e.target.closest('button'))return;const r=e.currentTarget.getBoundingClientRect();birdGoal={x:(e.clientX-r.left)/r.width,y:(e.clientY-r.top)/r.height};});}
function scan(){const points=[{x:.38,y:.57},{x:.68,y:.37}],i=points.findIndex(p=>Math.hypot(birdPos.x-p.x,birdPos.y-p.y)<.15);if(i<0){say('조금 더 가까이 날아가서 살펴봐!');return;}if(!state.survey.includes(i))state.survey.push(i);sfx.glimmer();app.querySelector(`[data-survey-target="${i}"]`).textContent='✓';app.querySelector('#q-survey-count').textContent=`${state.survey.length} / 2 봉분 조사`;say(i===0?'남쪽 무덤에서는 소중히 고친 유리병을 만났지!':'북쪽 무덤에서는 화려한 금 허리띠를 만났어!');dirty();if(state.survey.length===2){if(!replay)completeMission(state,5,null,['bird']);else state.practice++;ending();}}
function ending(){render('ending',`${nav('친구들이 이어 준 신라의 기억','여섯 기억을 모아, 우리의 지도가 완성됐어!')}<div class="q-ending-team">${state.friends.map(w=>actor(w)).join('')}</div><div class="q-memory-map">${state.relics.map(id=>`<button data-fact="${id}">${art(id)}<strong>${itemById(id).clue}</strong></button>`).join('')}</div><p class="q-speech">화려하게 꾸미고, 말을 타고, 먼 곳과 물건을 주고받고, 아끼는 물건을 고쳐 썼어.<br>무덤 주인의 정확한 이름은 아직 몰라. 하지만 남긴 흔적은 우리가 찾았지!</p><div class="q-ending-actions">${button('네 친구로 다시 발굴하기','map','q-primary')}${button('내 전시 꾸미기','museum')}${button('유물 이야기 다시 보기','facts:crown')}</div><p class="q-footnote">열린 다섯 발굴터에서 능력을 조합해 다시 놀 수 있어. 재발굴 ${state.practice}회</p>`);}
function friends(){render('friends',`${nav('얻은 친구가 곧 발굴 도구!','발굴을 마치면 다음 친구가 합류해')}<div class="q-friend-cards">${['frog','bird','turtle','snake'].map((w,i)=>`<article class="${state.friends.includes(w)?'':'locked'}">${actor(w)}<small>${state.friends.includes(w)?'함께하는 친구':i===0?'첫 탐험에서 깨우기':`${i}번째 발굴 뒤 합류`}</small><h3>${NAMES[w]}</h3><strong>${POWERS[w]}</strong><p>${{frog:'흙 위를 누르면 넓게 걷어 줘.',bird:'묻힌 유물의 위치를 찾아 줘.',turtle:'드러난 돌을 밀어 길을 내 줘.',snake:'나무 틈을 열어 마지막 붓질을 도와줘.'}[w]}</p></article>`).join('')}</div>${button('능력으로 발굴하러 가기','continue','q-primary')}`);}
function museum(){render('museum',`${nav('우리의 작은 전시실','전시는 선택! 발굴은 언제든 계속할 수 있어')}<div class="q-museum-layout"><div class="q-museum-room" data-decor="${state.decor}"><canvas class="q-museum-backdrop" data-material="museum"></canvas><div class="q-plinths">${state.slots.map((id,i)=>`<button type="button" data-slot="${i}" aria-label="${i+1}번 전시대 ${id?itemById(id).name:'비어 있음'}">${id?art(id):'<b>＋</b>'}<span>${id?itemById(id).name:'여기에 놓기'}</span></button>`).join('')}</div></div><aside><h3>내가 찾은 유물</h3><p>유물을 고르고 전시대를 눌러 봐.</p><div class="q-relic-tray">${state.relics.map(id=>`<button data-pick="${id}" aria-pressed="${selected===id}">${art(id)}<span>${itemById(id).name}</span></button>`).join('')||'<p>첫 발굴에서 유물을 만나자!</p>'}</div>${selected?button('선택한 유물 이야기','facts:'+selected):''}<div class="q-decor">${['포근한 빛','초록빛','저녁빛'].map((s,i)=>`<button data-decor="${i}" aria-pressed="${state.decor===i}">${s}</button>`).join('')}</div>${button('다음 발굴로!',state.step>=6?'map':'continue','q-primary')}</aside></div>`);}
function facts(id){const f=ARTIFACT_STORIES[id];if(!f)return;const modal=document.createElement('dialog');modal.className='q-facts';modal.innerHTML=`<button class="q-close" data-close aria-label="유물 이야기 닫기">닫기 ×</button><h2>${itemById(id).name}</h2><div class="q-passport"><span>${f.period}</span><span>${f.age}</span><span>${f.place}</span></div><div class="q-fact-grid">${art(id)}<div><h3>${f.what}</h3><p>${f.hello.join('<br>')}</p>${f.spots.map((p,i)=>`<button data-feature="${i}">${p.label}</button>`).join('')}<p class="q-fact-talk" role="status">${f.note}</p></div></div><p class="q-footnote">유물을 바탕으로 만든 놀이용 삽화 · <a href="${f.source}" target="_blank" rel="noopener">이야기 근거 자료</a></p>`;app.append(modal);modal.querySelector('[data-close]').onclick=()=>modal.close();modal.addEventListener('close',()=>modal.remove());modal.addEventListener('click',e=>{const b=e.target.closest('[data-feature]');if(b)modal.querySelector('.q-fact-talk').innerHTML=f.spots[Number(b.dataset.feature)].talk.join('<br>');});modal.showModal();paint(performance.now());}
app.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||b.disabled)return;sfx.unlock();if(b.dataset.action){const a=b.dataset.action;if(a.startsWith('facts:')){facts(a.slice(6));return;}if(a==='home')home();if(a==='map')map();if(a==='friends')friends();if(a==='museum')museum();if(a==='ending')ending();if(a==='continue')enter();if(a==='new'){state=freshQuest();site=null;selected='';replay=false;wake();}if(a==='wake-go')enter(0);if(a==='scan')scan();return;}
 if(b.dataset.patch!==undefined){patches.add(Number(b.dataset.patch));b.hidden=true;if(patches.size===3){wakeToad(state);say('두꺼비: 폴짝! 내가 흙을 넓게 걷어 줄게!');app.querySelector('[data-action="wake-go"]').classList.remove('hidden');sfx.found();dirty();}return;}
 if(b.dataset.mission!==undefined){enter(Number(b.dataset.mission));return;}
 if(b.dataset.tool){if(busy)return;tool=b.dataset.tool;updateTools();return;}
 if(b.dataset.scanCell!==undefined){power(Number(b.dataset.scanCell));return;}
 if(b.dataset.surveyTarget!==undefined){birdGoal=Number(b.dataset.surveyTarget)===0?{x:.38,y:.57}:{x:.68,y:.37};return;}
 if(b.dataset.fly){const [dx,dy]=b.dataset.fly.split(',').map(Number);birdGoal=null;birdPos={x:Math.max(.05,Math.min(.95,birdPos.x+dx*.1)),y:Math.max(.05,Math.min(.95,birdPos.y+dy*.1))};return;}
 if(b.dataset.fact){facts(b.dataset.fact);return;}
 if(b.dataset.pick){selected=b.dataset.pick;museum();return;}
 if(b.dataset.slot!==undefined&&selected){placeRelic(state,selected,Number(b.dataset.slot));museum();return;}
 if(b.dataset.decor!==undefined){state.decor=Number(b.dataset.decor);museum();}
});
saveButton.addEventListener('click',()=>{if(busy)return;capture();if(writeQuest(storage,state)){saved=JSON.stringify(state);dirty();status.textContent='여기까지 저장했어!';}else status.textContent='저장하지 못했어. 다시 눌러 줘.';});
function paint(t){for(const c of app.querySelectorAll('canvas[data-actor],canvas[data-art],canvas[data-material]')){const r=c.getBoundingClientRect(),dp=Math.min(devicePixelRatio||1,2),w=Math.round(r.width*dp),h=Math.round(r.height*dp);if(!w||!h)continue;if(c.width!==w||c.height!==h){c.width=w;c.height=h;}const ctx=c.getContext('2d');ctx.clearRect(0,0,w,h);if(c.dataset.actor)drawCharacter(ctx,c.dataset.actor,w/2,h*.96,Math.min(w,h)*.98,t,view==='reward'?'artifactRevealed':'idle',false,reduced.matches);else if(c.dataset.art){if(!drawGeneratedArtifact(ctx,c.dataset.art,0,0,w,h))drawArtifact(ctx,c.dataset.art,0,0,w,h);}else paintMaterial(ctx,c.dataset.material,w,h);}}
function frame(t){paint(t);if(view==='dig'&&renderer&&layout){renderer.draw(site,layout,t,'dig');if(scanned&&tool==='bird')renderer.hint([...site.artifactCells],t+1000);}if(view==='survey'){const dt=Math.min(1,(t-lastFrame)/1000);if(birdGoal){const dx=birdGoal.x-birdPos.x,dy=birdGoal.y-birdPos.y,d=Math.hypot(dx,dy),step=Math.min(d,dt*.6);if(d>.005){birdPos.x+=dx/d*step;birdPos.y+=dy/d*step;}else birdGoal=null;}const bird=app.querySelector('#q-survey-bird');bird.style.left=`${birdPos.x*100}%`;bird.style.top=`${birdPos.y*100}%`;}lastFrame=t;requestAnimationFrame(frame);}
home();requestAnimationFrame(frame);
